// The repository capabilities an abaify agent works through, and nothing
// else: it reads what it likes within bounds and changes a repository only
// by adding. A new file; text inserted before or after a unique anchor
// line, with the original bytes kept in order; a dependency added to
// package.json, which is re-serialized by a structured edit; the manifest
// regenerated by the program's own entry, replacing abaigram.yaml when
// there was one; the dependencies installed, which rewrites the lock file
// and node_modules. No source line the repository had is ever removed or
// reordered. Every change is recorded for the report and emitted as
// abaikit's own `repo.changed` event.
import { existsSync, mkdirSync, readdirSync, readFileSync, realpathSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import type { Abaigram } from "@abaigram/abai-stub";
import { runCommand, subjectEnv } from "./command.ts";
import { UsageError } from "./io.ts";
import { packageSpecs } from "./learnabai.ts";
import { shellQuote } from "./subject.ts";

export const LIST_CAP = 400;
export const LIST_CAP_BYTES = 12_000;
export const READ_CAP_LINES = 400;
export const READ_CAP_BYTES = 12_000;
export const INSTALL_TIMEOUT_MS = 10 * 60_000;
export const MANIFEST_TIMEOUT_MS = 60_000;

/** Trees skipped everywhere. */
export const SKIPPED_EVERYWHERE = new Set([".git", "node_modules"]);
/** Trees skipped at the root: build output, vendored and generated sites (a `src/build/` is the program's own). */
export const SKIPPED_AT_ROOT = new Set([
	"dist",
	"build",
	"third_party",
	"vendor",
	"website",
	"docs",
	"coverage",
	".turbo",
	".next",
	"out",
]);

export interface Change {
	how: "write" | "insert" | "add_dependency" | "manifest" | "install";
	path: string;
	why: string;
	detail: string;
	/** Added to the repository (a new file, inserted lines) or rewritten in place by a structured tool. */
	kind: "added" | "rewritten";
	at: string;
}

export interface RepoContext {
	/** Where relative `repo` arguments resolve. */
	cwd: string;
	env: NodeJS.ProcessEnv;
	/** The abaigram whose `repo.changed` event every change goes to; undefined under a plain unit test. */
	app?: Abaigram;
	/** Nothing is written; the write capabilities say what they would do. */
	dryRun?: boolean;
	changes: Change[];
	/** Told of each change as it happens, for a person watching. */
	onChange?: (change: Change) => void;
	/** Files this run created, which it may write again: nothing the repository had. */
	created?: Set<string>;
}

function str(params: Record<string, unknown>, name: string, required = true): string {
	const value = params[name];
	if (typeof value === "string" && value !== "") return value;
	if (required) throw new UsageError(`${name} is required`);
	return "";
}

function text(params: Record<string, unknown>, name: string): string {
	const value = params[name];
	if (typeof value !== "string") throw new UsageError(`${name} is required (a string, empty allowed)`);
	return value;
}

function num(params: Record<string, unknown>, name: string): number | undefined {
	const value = params[name];
	if (value === undefined || value === null) return undefined;
	if (typeof value !== "number" || !Number.isInteger(value) || value < 0)
		throw new UsageError(`${name} must be a whole number`);
	return value;
}

/** The repository root, an existing directory; and a path inside it, never outside. */
function repoRoot(ctx: RepoContext, params: Record<string, unknown>): string {
	const root = resolve(ctx.cwd, str(params, "repo"));
	if (!existsSync(root) || !statSync(root).isDirectory()) throw new UsageError(`${root} is not a directory`);
	return root;
}

/** The real path of the nearest existing ancestor plus the rest, so a symlink pointing out is seen. */
function realish(path: string): string {
	let existing = path;
	const rest: string[] = [];
	while (!existsSync(existing)) {
		const parent = dirname(existing);
		if (parent === existing) break;
		rest.unshift(existing.slice(parent.length + 1));
		existing = parent;
	}
	return join(realpathSync(existing), ...rest);
}

function inside(root: string, path: string): string {
	const realRoot = realpathSync(root);
	const full = realish(resolve(root, path));
	if (full !== realRoot && !full.startsWith(realRoot + sep)) throw new UsageError(`${path} is outside the repository`);
	return resolve(root, path);
}

// ---------------------------------------------------------------------------
// .gitignore, enough of it: names, anchored paths, directory rules, `*` and `?`;
// no negations, no character classes (they are escaped, so never match)
// ---------------------------------------------------------------------------

interface IgnoreRule {
	regex: RegExp;
	dirOnly: boolean;
	anchored: boolean;
}

function globToRegex(glob: string): string {
	let out = "";
	for (let i = 0; i < glob.length; i++) {
		const c = glob[i];
		if (c === "*") {
			if (glob[i + 1] === "*") {
				out += ".*";
				i += 1;
				if (glob[i + 1] === "/") i += 1;
			} else out += "[^/]*";
		} else if (c === "?") out += "[^/]";
		else out += c.replace(/[.+^${}()|[\]\\]/g, "\\$&");
	}
	return out;
}

export function ignoreRules(root: string): IgnoreRule[] {
	const file = join(root, ".gitignore");
	if (!existsSync(file)) return [];
	const rules: IgnoreRule[] = [];
	for (const raw of readFileSync(file, "utf8").split("\n")) {
		const line = raw.trim();
		if (line === "" || line.startsWith("#") || line.startsWith("!")) continue;
		const dirOnly = line.endsWith("/");
		let pattern = dirOnly ? line.slice(0, -1) : line;
		const anchored = pattern.startsWith("/") || pattern.includes("/");
		if (pattern.startsWith("/")) pattern = pattern.slice(1);
		rules.push({ regex: new RegExp(`^${globToRegex(pattern)}$`), dirOnly, anchored });
	}
	return rules;
}

function ignored(rules: IgnoreRule[], relativePath: string, isDir: boolean): boolean {
	const name = relativePath.split("/").at(-1) ?? "";
	return rules.some((rule) => {
		if (rule.dirOnly && !isDir) return false;
		return rule.anchored ? rule.regex.test(relativePath) : rule.regex.test(name);
	});
}

function skipped(rules: IgnoreRule[], name: string, rel: string, depth: number): boolean {
	if (SKIPPED_EVERYWHERE.has(name)) return true;
	if (depth === 0 && SKIPPED_AT_ROOT.has(name)) return true;
	return ignored(rules, rel, true);
}

// ---------------------------------------------------------------------------
// Reading
// ---------------------------------------------------------------------------

export interface Listing {
	/** Entries in `listing`. */
	count: number;
	/** Files that matched, listed or not. */
	total: number;
	listing: string;
	truncated: number;
}

/** Every file under `dir` (relative paths), the skips applied, in sorted order. */
function walk(root: string, rules: IgnoreRule[], dir: string, depth: number, visit: (rel: string) => void): void {
	let entries: string[];
	try {
		entries = readdirSync(dir).sort();
	} catch {
		return;
	}
	for (const name of entries) {
		const full = join(dir, name);
		const rel = relative(root, full).split(sep).join("/");
		let isDir: boolean;
		try {
			isDir = statSync(full).isDirectory();
		} catch {
			continue;
		}
		if (isDir) {
			if (!skipped(rules, name, rel, depth)) walk(root, rules, full, depth + 1, visit);
			continue;
		}
		if (!ignored(rules, rel, false)) visit(rel);
	}
}

/**
 * `repo.list`: files under the root, skipping what no retrofit reads,
 * bounded by entries and bytes, the bound said first. A glob narrows:
 * `*.json` by name anywhere, `src/**` or `scripts/*.mjs` by path.
 */
export function listRepo(root: string, glob?: string): Listing {
	const rules = ignoreRules(root);
	const filter = glob ? new RegExp(`^${globToRegex(glob)}$`) : undefined;
	const found: string[] = [];
	let total = 0;
	let bytes = 0;
	walk(root, rules, root, 0, (rel) => {
		if (filter && !filter.test(rel) && !filter.test(rel.split("/").at(-1) ?? "")) return;
		total += 1;
		if (found.length >= LIST_CAP || bytes + rel.length + 1 > LIST_CAP_BYTES) return;
		found.push(rel);
		bytes += rel.length + 1;
	});
	const truncated = total - found.length;
	const head =
		truncated > 0
			? `[${found.length} of ${total} files listed; ${truncated} more: narrow with glob, such as src/** or *.ts]\n`
			: "";
	return { count: found.length, total, listing: head + found.join("\n"), truncated };
}

/** The shape of a repository for a brief: the files at the root, and each directory with its file count. */
export function summarizeRepo(root: string): { total: number; summary: string } {
	const rules = ignoreRules(root);
	const files: string[] = [];
	const dirs: Array<{ name: string; files: number }> = [];
	let total = 0;
	for (const name of readdirSync(root).sort()) {
		const full = join(root, name);
		let isDir: boolean;
		try {
			isDir = statSync(full).isDirectory();
		} catch {
			continue;
		}
		if (isDir) {
			if (skipped(rules, name, name, 0)) continue;
			let n = 0;
			walk(root, rules, full, 1, () => {
				n += 1;
			});
			dirs.push({ name, files: n });
			total += n;
		} else if (!ignored(rules, name, false)) {
			files.push(name);
			total += 1;
		}
	}
	const lines = [...files, ...dirs.map((d) => `${d.name}/ (${d.files} file${d.files === 1 ? "" : "s"})`)];
	return { total, summary: lines.join("\n") };
}

/** `repo.read`: a window of a file from line `start` (1-based), at most `READ_CAP_LINES` lines and `READ_CAP_BYTES` bytes. */
export function readRepo(
	root: string,
	path: string,
	start = 1,
	lines = READ_CAP_LINES,
): { text: string; total_lines: number; from: number; to: number } {
	const full = inside(root, path);
	if (!existsSync(full) || statSync(full).isDirectory()) throw new UsageError(`${path}: no such file`);
	const all = readFileSync(full, "utf8").split("\n");
	const count = Math.min(Math.max(1, lines), READ_CAP_LINES);
	const from = Math.max(1, start);
	const picked: string[] = [];
	let bytes = 0;
	for (const line of all.slice(from - 1, from - 1 + count)) {
		if (picked.length > 0 && bytes + line.length + 1 > READ_CAP_BYTES) break;
		picked.push(line);
		bytes += line.length + 1;
	}
	return { text: picked.join("\n"), total_lines: all.length, from, to: from - 1 + picked.length };
}

// ---------------------------------------------------------------------------
// Adding
// ---------------------------------------------------------------------------

function record(ctx: RepoContext, change: Omit<Change, "at">): void {
	const full = { ...change, at: new Date().toISOString() };
	ctx.changes.push(full);
	ctx.onChange?.(full);
	ctx.app?.event("repo.changed").emit({ path: change.path, how: change.how });
}

/**
 * `repo.write`: a new file, or one this run made and may now correct; a
 * file the repository had is refused, since abaify adds and never replaces.
 */
export function writeRepo(
	ctx: RepoContext,
	root: string,
	path: string,
	content: string,
	why: string,
): { written: boolean; path: string } {
	const full = inside(root, path);
	const own = ctx.created?.has(full) === true;
	if (existsSync(full) && !own) {
		throw new UsageError(
			`${path} exists already; repo.write makes new files only (repo.insert adds to an existing one)`,
		);
	}
	const lines = content.split("\n").length;
	if (ctx.dryRun) {
		record(ctx, {
			how: "write",
			path,
			why,
			kind: "added",
			detail: `dry run: would write ${content.length} characters`,
		});
		ctx.created?.add(full);
		return { written: false, path };
	}
	mkdirSync(dirname(full), { recursive: true });
	writeFileSync(full, content);
	ctx.created?.add(full);
	record(ctx, {
		how: "write",
		path,
		why,
		kind: "added",
		detail: own ? `${lines} lines (this run's own file, written again)` : `${lines} lines`,
	});
	return { written: true, path };
}

/** `repo.insert`: `text` before or after the one line equal to `anchor` (trimmed); the original bytes stay, in order. */
export function insertRepo(
	ctx: RepoContext,
	root: string,
	path: string,
	anchor: string,
	where: string,
	text: string,
	why: string,
): { line: number; path: string } {
	if (where !== "before" && where !== "after") throw new UsageError(`where must be before or after, not ${where}`);
	const full = inside(root, path);
	if (!existsSync(full) || statSync(full).isDirectory())
		throw new UsageError(`${path}: no such file (repo.write makes a new one)`);
	const original = readFileSync(full, "utf8");
	const lines = original.split("\n");
	const wanted = anchor.trim();
	if (wanted === "") throw new UsageError("anchor must be a line of the file");
	const hits = lines.map((l, i) => (l.trim() === wanted ? i : -1)).filter((i) => i >= 0);
	if (hits.length === 0) throw new UsageError(`${path}: no line reads ${JSON.stringify(wanted)}`);
	if (hits.length > 1)
		throw new UsageError(
			`${path}: ${hits.length} lines read ${JSON.stringify(wanted)} (lines ${hits.map((i) => i + 1).join(", ")}); the anchor must be unique`,
		);
	const at = hits[0] + (where === "after" ? 1 : 0);
	const inserted = text.replace(/\n$/, "").split("\n");
	if (ctx.dryRun) {
		record(ctx, {
			how: "insert",
			path,
			why,
			kind: "added",
			detail: `dry run: would insert ${inserted.length} lines ${where} line ${hits[0] + 1}`,
		});
		return { line: at + 1, path };
	}
	const before = lines.slice(0, at).join("\n");
	const after = lines.slice(at).join("\n");
	const updated = [...lines.slice(0, at), ...inserted, ...lines.slice(at)].join("\n");
	// the additive guarantee, checked, not assumed: what was there is still there, in order, around the insert
	if (!updated.startsWith(before) || !updated.endsWith(after)) {
		throw new Error(`${path}: the insert would not have been additive; nothing was written`);
	}
	writeFileSync(full, updated);
	record(ctx, {
		how: "insert",
		path,
		why,
		kind: "added",
		detail: `${inserted.length} lines ${where} line ${hits[0] + 1}`,
	});
	return { line: at + 1, path };
}

/** The indentation a JSON file uses, so an edit keeps its shape. */
function indentOf(text: string): string {
	const match = /^(\t+| +)"/m.exec(text);
	return match ? match[1] : "  ";
}

/** `repo.add_dependency`: one entry added to `dependencies`, in sorted place; an existing one is left as it is and said. */
export function addDependency(
	ctx: RepoContext,
	root: string,
	name: string,
	spec: string | undefined,
	why: string,
): { spec: string; added: boolean } {
	const file = inside(root, "package.json");
	if (!existsSync(file)) throw new UsageError("package.json: no such file; repo.add_dependency needs one");
	const original = readFileSync(file, "utf8");
	let pkg: Record<string, unknown>;
	try {
		pkg = JSON.parse(original) as Record<string, unknown>;
	} catch (error) {
		throw new UsageError(`package.json does not parse: ${error instanceof Error ? error.message : String(error)}`);
	}
	const known = packageSpecs().dependency;
	const chosen =
		spec ??
		(name === "@abaigram/abai-stub"
			? known.abai
			: name === "@abaigram/abai-embedded-harness"
				? known.harness
				: name === "@abaigram/abaikit"
					? known.abaikit
					: undefined);
	if (chosen === undefined)
		throw new UsageError(
			`${name} needs a spec; only @abaigram/abai-stub, @abaigram/abai-embedded-harness and @abaigram/abaikit have a default here`,
		);
	const deps = (pkg.dependencies ?? {}) as Record<string, string>;
	if (deps[name] !== undefined) return { spec: deps[name], added: false };
	if (ctx.dryRun) {
		record(ctx, {
			how: "add_dependency",
			path: "package.json",
			why,
			kind: "rewritten",
			detail: `dry run: would add ${name}: ${chosen}`,
		});
		return { spec: chosen, added: false };
	}
	const sorted: Record<string, string> = {};
	for (const key of [...Object.keys(deps), name].sort()) sorted[key] = key === name ? chosen : deps[key];
	pkg.dependencies = sorted;
	const eol = original.includes("\r\n") ? "\r\n" : "\n";
	const serialized = JSON.stringify(pkg, null, indentOf(original)).split("\n").join(eol);
	writeFileSync(file, `${serialized}${/\r?\n$/.test(original) ? eol : ""}`);
	record(ctx, {
		how: "add_dependency",
		path: "package.json",
		why,
		kind: "rewritten",
		detail: `${name}: ${chosen} (the file re-serialized, keys and indentation kept)`,
	});
	return { spec: chosen, added: true };
}

/** `repo.manifest`: the program's own `<entry> manifest`, written to abaigram.yaml, the one file never written by hand. */
export async function regenerateManifest(
	ctx: RepoContext,
	root: string,
	entry: string,
	why: string,
): Promise<{ written: boolean; lines: number; text: string }> {
	const run = await runCommand(`${entry} manifest`, {
		cwd: root,
		env: subjectEnv(ctx.env),
		timeoutMs: MANIFEST_TIMEOUT_MS,
	});
	if (run.code !== 0 || run.timedOut) {
		const last = run.stderr.trim().split("\n").at(-1) ?? "";
		throw new UsageError(
			`${entry} manifest ${run.timedOut ? "did not finish" : `exited ${run.code ?? run.signal}`}: ${last || "no output"}`,
		);
	}
	if (!run.stdout.includes("abaigrammar:"))
		throw new UsageError(`${entry} manifest printed no manifest: ${run.stdout.slice(0, 200)}`);
	const target = join(root, "abaigram.yaml");
	const previous = existsSync(target) ? readFileSync(target, "utf8").split("\n").length : undefined;
	const lines = run.stdout.split("\n").length;
	if (ctx.dryRun) {
		record(ctx, {
			how: "manifest",
			path: "abaigram.yaml",
			why,
			kind: previous === undefined ? "added" : "rewritten",
			detail: "dry run (the entry was run, read-only): would write what it prints",
		});
		return { written: false, lines, text: run.stdout };
	}
	writeFileSync(target, run.stdout);
	record(ctx, {
		how: "manifest",
		path: "abaigram.yaml",
		why,
		kind: previous === undefined ? "added" : "rewritten",
		detail: `${lines} lines, from ${entry} manifest${previous === undefined ? "" : ` (replaced a previous ${previous}-line file)`}`,
	});
	return { written: true, lines, text: run.stdout };
}

/** `repo.install`: `npm install` in the root, bounded; the one step that reaches the network and runs the repository's own install scripts. */
export async function installRepo(
	ctx: RepoContext,
	root: string,
	why: string,
): Promise<{ ok: boolean; output: string }> {
	if (ctx.dryRun) {
		record(ctx, {
			how: "install",
			path: "node_modules",
			why,
			kind: "rewritten",
			detail: "dry run: would run npm install",
		});
		return { ok: true, output: "dry run" };
	}
	const run = await runCommand(`npm install ${shellQuote("--no-audit")} ${shellQuote("--no-fund")}`, {
		cwd: root,
		env: subjectEnv(ctx.env),
		timeoutMs: INSTALL_TIMEOUT_MS,
	});
	const tail = `${run.stdout}\n${run.stderr}`.trim().split("\n").slice(-12).join("\n");
	record(ctx, {
		how: "install",
		path: "node_modules",
		why,
		kind: "rewritten",
		detail: run.code === 0 ? "npm install ok" : `npm install failed (${run.code ?? run.signal})`,
	});
	if (existsSync(join(root, "package-lock.json"))) {
		record(ctx, {
			how: "install",
			path: "package-lock.json",
			why,
			kind: "rewritten",
			detail: "written by npm install",
		});
	}
	if (run.code !== 0) throw new UsageError(`npm install failed: ${tail}`);
	return { ok: true, output: tail };
}

/** The capabilities, bound to a context, in the shape abaikit's manifest declares them. */
export function repoHandlers(ctx: RepoContext): Record<string, (params: Record<string, unknown>) => unknown> {
	return {
		"repo.list": (p) => {
			const { count, total, listing } = listRepo(repoRoot(ctx, p), str(p, "glob", false) || undefined);
			return { count, total, listing };
		},
		"repo.read": (p) =>
			readRepo(repoRoot(ctx, p), str(p, "path"), num(p, "start") ?? 1, num(p, "lines") ?? READ_CAP_LINES),
		"repo.write": (p) => writeRepo(ctx, repoRoot(ctx, p), str(p, "path"), text(p, "content"), str(p, "why")),
		"repo.insert": (p) =>
			insertRepo(
				ctx,
				repoRoot(ctx, p),
				str(p, "path"),
				str(p, "anchor"),
				str(p, "where"),
				text(p, "text"),
				str(p, "why"),
			),
		"repo.add_dependency": (p) =>
			addDependency(ctx, repoRoot(ctx, p), str(p, "name"), str(p, "spec", false) || undefined, str(p, "why")),
		"repo.manifest": (p) => regenerateManifest(ctx, repoRoot(ctx, p), str(p, "entry"), str(p, "why")),
		"repo.install": (p) => installRepo(ctx, repoRoot(ctx, p), str(p, "why")),
	};
}
